"""Bake existing HD grass contours over exact, unresampled five-row RGB crops."""
from pathlib import Path
from PIL import Image
import numpy as np,json,hashlib,shutil
W=Path('assets/source-art/work');cp=Path('assets/source-art/catalog.json');cat=json.loads(cp.read_text());E={e['id']:e for e in cat['entries']};source=Path(E['images/background1']['export4x']['path']);five=Image.open(source).convert('RGBA');batch=W/'pending-audit/rebuilt-candidates.json';doc=json.loads(batch.read_text());proof=[]
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
for name,x,y,w,h in [('sod1row',239,265,771,127),('sod3row',235,149,771,355)]:
 key='images/'+name;e=E[key];assert e['status']=='pending';d=W/key;archive=d/'attempts/direct-ai-short-prompt';archive.mkdir(parents=True,exist_ok=True)
 for f in ['candidate-4x.png','recipe.json']:
  if not (archive/f).exists():shutil.copy2(d/f,archive/f)
 contourSource=archive/'candidate-4x.png';contour=Image.open(contourSource).convert('RGBA').getchannel('A');assert contour.size==(w*4,h*4);contour.save(d/'contour-alpha-4x.png');crop=five.crop((x*4,y*4,(x+w)*4,(y+h)*4));expectedRGB=np.array(crop)[:,:,:3].copy();crop.putalpha(contour);dest=d/'candidate-4x.png';crop.save(dest,compress_level=1);actual=np.array(Image.open(dest));assert np.array_equal(actual[:,:,:3],expectedRGB);assert np.array_equal(actual[:,:,3],np.array(contour))
 record={'id':key,'candidate':dest.as_posix(),'sha256':sha(dest),'logicalSize':[w,h],'physicalSize':[w*4,h*4],'baseline':e['current']['path'],'method':'离线合成：五行高清地图按原坐标直接裁切RGB，仅使用现有单行/三行高清轮廓的alpha；RGB不缩放、不校色，最终为独立RGBA PNG','sources':[source.as_posix(),contourSource.as_posix()],'mapLogicalRect':[x,y,w,h],'originalDrawLogical':[x-220,y],'mapCropPixels4x':[x*4,y*4,w*4,h*4],'contourSourceSha256':sha(contourSource),'mapSourceSha256':sha(source),'sourceRGBPixelIdentical':True,'contourAlphaByteIdentical':True,'externalRuntimeMask':None,'runtime2xUsedAsSource':False,'reviewStatus':'pending','runtimeBindingChanged':False,'kind':'images','group':'场景与地图','original':e['original']};(d/'recipe.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');i=next(i for i,r in enumerate(doc['items']) if r['id']==key);doc['items'][i]=record;e['repairCandidate'].update(sha256=record['sha256'],reviewStatus='pending');e['repairCandidate'].pop('thumbnail',None);proof.append({'id':key,'allRGBPixelsMatchFiveRowCrop':True,'allAlphaBytesMatchHDContourCandidate':True,'cropPixels':record['mapCropPixels4x'],'runtimeExternalMask':False})
batch.write_text(json.dumps(doc,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');cp.write_text(json.dumps(cat,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');(W/'pending-audit/grass-five-row-mask-proof.json').write_text(json.dumps({'items':proof,'productionBindingsChanged':False},ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(json.dumps(proof,ensure_ascii=False))
